@page "/board"
@using sv_a82a9c3f30fe4abcab743fd2435a7841.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p><em>Loading tasks...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <!-- Summary Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @allTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @ToDoTasks.Count()</span>
        <span class="stat-item"><strong>In Progress:</strong> @InProgressTasks.Count()</span>
        <span class="stat-item"><strong>Done:</strong> @DoneTasks.Count()</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @OverdueCount</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-columns">
        <!-- To Do Column -->
        <div class="board-column">
            <div class="column-header">
                <h3>To Do <span class="badge">@FilteredToDoTasks.Count()</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in FilteredToDoTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveRight(task)">Move Right &rarr;</button>
                        </div>
                    </div>
                }
            </div>
            @if (showAddForm["To Do"])
            {
                <div class="add-task-form">
                    <input type="text" class="form-control" placeholder="Title" @bind="newTitle" />
                    <input type="text" class="form-control" placeholder="Assignee" @bind="newAssignee" />
                    <select class="form-control" @bind="newPriority">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" class="form-control" @bind="newDueDate" />
                    <div class="form-buttons">
                        <button class="btn btn-success btn-sm" @onclick="() => SaveTask(\"To Do\")">Save</button>
                        <button class="btn btn-secondary btn-sm" @onclick="() => CancelAdd(\"To Do\")">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-outline-secondary btn-sm add-task-btn" @onclick="() => ShowAdd(\"To Do\")">+ Add Task</button>
            }
        </div>

        <!-- In Progress Column -->
        <div class="board-column">
            <div class="column-header">
                <h3>In Progress <span class="badge">@FilteredInProgressTasks.Count()</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in FilteredInProgressTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveLeft(task)">&larr; Move Left</button>
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveRight(task)">Move Right &rarr;</button>
                        </div>
                    </div>
                }
            </div>
            @if (showAddForm["In Progress"])
            {
                <div class="add-task-form">
                    <input type="text" class="form-control" placeholder="Title" @bind="newTitle" />
                    <input type="text" class="form-control" placeholder="Assignee" @bind="newAssignee" />
                    <select class="form-control" @bind="newPriority">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" class="form-control" @bind="newDueDate" />
                    <div class="form-buttons">
                        <button class="btn btn-success btn-sm" @onclick="() => SaveTask(\"In Progress\")">Save</button>
                        <button class="btn btn-secondary btn-sm" @onclick="() => CancelAdd(\"In Progress\")">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-outline-secondary btn-sm add-task-btn" @onclick="() => ShowAdd(\"In Progress\")">+ Add Task</button>
            }
        </div>

        <!-- Done Column -->
        <div class="board-column">
            <div class="column-header">
                <h3>Done <span class="badge">@FilteredDoneTasks.Count()</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in FilteredDoneTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveLeft(task)">&larr; Move Left</button>
                        </div>
                    </div>
                }
            </div>
            @if (showAddForm["Done"])
            {
                <div class="add-task-form">
                    <input type="text" class="form-control" placeholder="Title" @bind="newTitle" />
                    <input type="text" class="form-control" placeholder="Assignee" @bind="newAssignee" />
                    <select class="form-control" @bind="newPriority">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" class="form-control" @bind="newDueDate" />
                    <div class="form-buttons">
                        <button class="btn btn-success btn-sm" @onclick="() => SaveTask(\"Done\")">Save</button>
                        <button class="btn btn-secondary btn-sm" @onclick="() => CancelAdd(\"Done\")">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-outline-secondary btn-sm add-task-btn" @onclick="() => ShowAdd(\"Done\")">+ Add Task</button>
            }
        </div>
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    // Add task form state
    private Dictionary<string, bool> showAddForm = new()
    {
        ["To Do"] = false,
        ["In Progress"] = false,
        ["Done"] = false
    };
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    private static readonly string[] ColumnOrder = { "To Do", "In Progress", "Done" };

    private IEnumerable<TaskItem> ToDoTasks => allTasks.Where(t => t.Status == "To Do");
    private IEnumerable<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress");
    private IEnumerable<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done");

    private IEnumerable<TaskItem> FilteredToDoTasks => FilterBySearch(ToDoTasks);
    private IEnumerable<TaskItem> FilteredInProgressTasks => FilterBySearch(InProgressTasks);
    private IEnumerable<TaskItem> FilteredDoneTasks => FilterBySearch(DoneTasks);

    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done");

    private IEnumerable<TaskItem> FilterBySearch(IEnumerable<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, task.Status);
        if (currentIndex <= 0) return;

        var newStatus = ColumnOrder[currentIndex - 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, task.Status);
        if (currentIndex >= ColumnOrder.Length - 1) return;

        var newStatus = ColumnOrder[currentIndex + 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAdd(string column)
    {
        ResetForm();
        showAddForm[column] = true;
    }

    private void CancelAdd(string column)
    {
        showAddForm[column] = false;
        ResetForm();
    }

    private async Task SaveTask(string column)
    {
        if (string.IsNullOrWhiteSpace(newTitle)) return;

        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            // The service creates tasks; we add it locally with the correct status
            allTasks.Add(created with { Status = column });
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
            }
            showAddForm[column] = false;
            ResetForm();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }

    private void ResetForm()
    {
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }
}

