arguments.file_text:
.stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat-item {
    font-size: 0.95rem;
}

.stat-overdue strong {
    color: #dc3545;
}

.search-bar {
    margin-bottom: 1rem;
    max-width: 400px;
}

.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 0.5rem;
    padding: 1rem;
    min-width: 250px;
}

.column-header h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

.column-header .badge {
    background: #6c757d;
    color: white;
    border-radius: 50%;
    padding: 0.2em 0.55em;
    font-size: 0.8rem;
    vertical-align: middle;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 0.75rem;
}

.task-card {
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 0.4rem;
    padding: 0.75rem;
    box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.task-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.task-assignee {
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.25rem;
}

.task-due {
    font-size: 0.8rem;
    color: #495057;
    margin-top: 0.25rem;
}

.task-actions {
